import { useState, useEffect } from "react";
import { X, Save } from "lucide-react";
import "../Style/PropertyDetailsForm.css";

const initialState = {
  ownerName: "",
  occupierName: "",
  address: "",
  mobile: "",
  ward: "",
  zone: "",
  newPropertyNo: "",
  oldPropertyNo: "",

  usageType: "Residential",
  constructionType: "A",
  constructionYear: "",
  area: "",
  rate: "",

  taxableValue: 0,
  deduction: 0,
  finalTaxableValue: 0,
  propertyTax: 0,
  educationTax: 0,
  treeTax: 0,
  fireTax: 0,
  totalTax: 0,
};

export default function PropertyDetailsForm({ isOpen, onClose }) {
  const [formData, setFormData] = useState(initialState);

  // ------------------------------
  // AUTO TAX CALCULATION
  // ------------------------------
  useEffect(() => {
    const area = parseFloat(formData.area) || 0;
    const rate = parseFloat(formData.rate) || 0;

    const taxableValue = area * rate;
    const deduction = taxableValue * 0.10; // 10% deduction
    const finalTaxableValue = taxableValue - deduction;

    // Example tax percentages (you can change later)
    const propertyTax = finalTaxableValue * 0.12;  // 12%
    const educationTax = finalTaxableValue * 0.02; // 2%
    const treeTax = finalTaxableValue * 0.01;      // 1%
    const fireTax = finalTaxableValue * 0.01;      // 1%

    const totalTax =
      propertyTax + educationTax + treeTax + fireTax;

    setFormData((prev) => ({
      ...prev,
      taxableValue,
      deduction,
      finalTaxableValue,
      propertyTax,
      educationTax,
      treeTax,
      fireTax,
      totalTax,
    }));
  }, [formData.area, formData.rate]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

const handleSave = async () => {
  const payload = {
    ...formData,
    location: {
      type: "Point",
      coordinates: [capturedLocation.lng, capturedLocation.lat]
    }
  };

  const res = await fetch("http://localhost:5001/api/property/save", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    alert("Failed to save property");
    return;
  }

  alert("Property saved successfully");
  onClose();
};

}
